# -*- coding: utf-8 -*-
from pathlib import Path
import json,html,re
D=Path('dist');posts=json.loads(Path('research-content.json').read_text());esc=html.escape
old=(D/'blog/index.html').read_text();header=re.search(r'<header class="wrap top">.*?</header>',old).group();footer=re.search(r'<footer.*?</footer>',old).group()
def head(title,desc):return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · Aitist</title><meta name="description" content="{esc(desc)}"><link rel="stylesheet" href="/assets/site.css"><link rel="stylesheet" href="/assets/sand.css?v=10"><link rel="stylesheet" href="/assets/research.css?v=1"><script src="/assets/research.js" defer></script></head>'
def img(p,cls=''):return f'<img class="{cls}" src="/assets/research/cover-{p["cover"]}.webp" width="1440" height="900" alt="" loading="lazy" decoding="async">'
def card(p):return f'<a class="study-card" href="/blog/{p["slug"]}/">{img(p)}<div><p class="mono">{p["category"]} / {p["date"]}</p><h3>{p["title"]}</h3><p>{p["summary"]}</p><span class="study-read">Read the research ↗</span></div></a>'
def table(p):
 t=p['table'];return '<figure class="data-table"><div class="table-scroll" tabindex="0" role="region" aria-label="Research measurement table"><table><thead><tr>'+''.join('<th scope="col">'+esc(x)+'</th>' for x in t['headers'])+'</tr></thead><tbody>'+''.join('<tr>'+''.join(('<th scope="row">'+esc(x)+'</th>') if j==0 else ('<td>'+esc(x)+'</td>') for j,x in enumerate(row))+'</tr>' for row in t['rows'])+'</tbody></table></div><figcaption>'+t['note']+'</figcaption></figure>'
for p in posts:
 extra = '<p class="evidence-link"><a href="'+p['extra_source']+'">Supporting deployment report ↗</a></p>' if p.get('extra_source') else ''
 toc=''.join(f'<li><a href="#section-{i}">{esc(x[0])}</a></li>' for i,x in enumerate(p['sections'],1))
 sections=''.join(f'<section id="section-{i}"><span class="mono">0{i}</span><h2>{esc(x[0])}</h2><p>{esc(x[1])}</p></section>' for i,x in enumerate(p['sections'],1))
 content=head(p['title'],p['summary'])+'<body class="journal research-edition"><a class="skip" href="#main">Skip to content</a>'+header+f'<main id="main"><div class="wrap paper"><a class="back" href="/blog/">← All research</a><header class="article-heading"><p class="mono">{p["category"]}</p><h1>{p["title"]}</h1><p class="byline">Aitist</p><p class="article-date">Published November 13, 2026 · Measurements: {p["date"]}</p></header><figure class="research-hero">{img(p)}<figcaption class="mono">Aitist / {p["category"]} · Stone study 0{p["cover"]+1}</figcaption></figure><div class="reading"><aside><details class="article-toc" open><summary class="mono">ON THIS PAGE</summary><ol>{toc}<li><a href="#evidence">Data & sources</a></li></ol></details></aside><article><div class="abstract"><span class="mono">ABSTRACT</span><p>{p["summary"]}</p></div>{sections}<section id="evidence"><h2>Data & sources</h2>{table(p)}<p class="evidence-link"><a href="{p["source"]}">Read the original technical report ↗</a></p>{extra}<p class="source-note">Reported measurements from Aitist’s supplied engineering reports. Results apply to the stated hardware and workload; they are not a service-level guarantee.</p></section><a class="more" href="/blog/">Explore all research ↗</a></article></div></div></main>'+footer+'<script src="/assets/section-stones.js?v=1" defer></script></body></html>'
 q=D/'blog'/p['slug'];q.mkdir(exist_ok=True);(q/'index.html').write_text(content)
(D/'blog/index.html').write_text(head('Research','Experiments, deployment results and methods from Aitist.')+'<body class="journal research-edition"><a class="skip" href="#main">Skip to content</a>'+header+'<main id="main"><section class="wrap archive"><p class="mono">Aitist / Research</p><h1>More from every chip.</h1><p class="lede">Experiments in efficient inference. The results, the trade-offs, and the evidence behind each decision.</p><div class="study-grid">'+''.join(map(card,posts))+'</div></section></main>'+footer+'<script src="/assets/section-stones.js?v=1" defer></script></body></html>')
home=(D/'index.html').read_text();home=home.replace('<script src="/assets/research.js" defer></script></head>','<link rel="stylesheet" href="/assets/research.css?v=1"><script src="/assets/research.js" defer></script></head>') if '/assets/research.css' not in home else home
start=re.search(r'<section[^>]+id="approach"[^>]*>',home).start();end=home.index('</main>',start)
body='''<section class="wrap rule results" id="approach"><div class="section-lead"><div><p class="mono">01 / MEASURED PROGRESS</p><h2>Small changes.<br>Material gains.</h2></div><p class="lede">We improve the path from GPU to useful output: communication, memory, scheduling and the behavior an agent depends on.</p></div><div class="result-grid">'''
for p in [posts[0],posts[1],posts[2]]:
 body+=f'<a class="result-card" href="/blog/{p["slug"]}/">{img(p)}<div><span class="metric">{p["metric"]}</span><p>{p["unit"]}</p><span class="mono">{p["category"]} · View conditions ↗</span></div></a>'
body+='''</div><p class="section-note">Selected October 2026 measurements. Each result links to its workload, configuration and limitations.</p></section>
<section class="wrap rule frontier" id="performance"><div class="section-lead"><div><p class="mono">02 / THE USEFUL FRONTIER</p><h2>More output.<br>A usable stream.</h2></div><p class="lede">Optimize total throughput while keeping each user above the chosen generation-speed threshold.</p></div><div class="frontier-layout"><figure class="feature-art"><img src="/assets/research/cover-2.webp" width="1440" height="900" alt="Three stone forms connected by a flowing sand ribbon" loading="lazy"></figure><div class="benchmark"><p class="mono">Kimi-K3 / 16 GPUs per configuration</p><div class="bar-row"><div><span>B200 · concurrency 64</span><strong>1,991 <small>tok/s</small></strong></div><span class="bar" style="--length:100%"></span><p>41 tok/s per user · broader acceptance pending</p></div><div class="bar-row"><div><span>H200 · concurrency 16</span><strong>496 <small>tok/s</small></strong></div><span class="bar" style="--length:24.9%"></span><p>40 tok/s per user · reported acceptance passed</p></div><p class="section-note">Corrected wall-clock throughput · ~7.6K uncached input / 1,024 output tokens. Different concurrency settings; not a same-load A/B.</p><a class="more" href="/blog/kimi-deployment-frontier/">Explore the deployment trade-offs ↗</a></div></div></section>
<section class="wrap rule" id="systems"><div class="section-lead"><div><p class="mono">03 / ENGINEERED END TO END</p><h2>Performance that<br>survives real work.</h2></div><p class="lede">A faster kernel is one part of the system. Long prompts, cached state and tool calls determine what users can actually build.</p></div><div class="system-grid">'''
for p,headline,detail in [(posts[1],'Long context','Retrieve information across a million-token prompt, with cache state and latency made explicit.'),(posts[4],'State-aware serving','Follow the bytes from prefill to decode. A high cache-hit rate can still hide expensive transfers.'),(posts[3],'Agent reliability','Check tool schemas, streamed responses and multi-turn behavior—not just the HTTP status.')]:
 body+=f'<a class="capability" href="/blog/{p["slug"]}/">{img(p)}<div><h3>{headline}</h3><p>{detail}</p><span class="study-read">Read the evidence ↗</span></div></a>' 
body+='''</div></section><section class="wrap rule" id="research"><div class="section-lead"><div><p class="mono">04 / RESEARCH</p><h2>Show the work.</h2></div><a class="research-link" href="/blog/">All research ↗</a></div><div class="study-grid">'''+''.join(map(card,posts))+'''</div></section>
<section class="wrap rule method" id="method"><figure class="feature-art"><img src="/assets/research/cover-5.webp" width="1440" height="900" alt="Stone forms arranged in a cycle with flowing grains" loading="lazy"></figure><div><p class="mono">05 / HOW WE WORK</p><h2>Every iteration<br>leaves a better starting point.</h2><p class="lede">Define a test. Measure the baseline. Challenge the conclusion. Validate a canary. Keep the evidence for the next round.</p><div class="method-data"><div><strong>227</strong><span>commits across two repositories</span></div><div><strong>36</strong><span>merged pull requests</span></div></div><p class="section-note">October 11–20, 2026 repository review. Engineers directed the work and approved production changes.</p><a class="more" href="/blog/evidence-driven-engineering/">Inside the engineering loop ↗</a></div></section>
<section class="wrap rule mission"><div><p class="mono">06 / OUR MISSION</p><h2>Bring AI within<br>everyone’s reach.</h2><p class="lede">Make more possible with every chip.</p><a class="sand-button primary" href="mailto:contact@aitist.ai">Build with Aitist ↗</a></div><img class="mission-stone" src="/assets/stones/00-cornerstone.webp" alt="" loading="lazy"></section>'''
home=home[:start]+body+home[end:];(D/'index.html').write_text(home)
